SELECT CASE WHEN sqft >= 12300 THEN 'PREMIUM' ELSE 'STANDARD' END AS sqft_tier, city, STDDEV_SAMP(sqft) AS sqft_stddev, ROUND(AVG(sqft), 2) AS avg_sqft, STDDEV_SAMP(sqft) AS sqft_stddev_2, AVG(sqft) AS avg_sqft_2, COUNT(DISTINCT city) AS distinct_cities, APPROX_PERCENTILE(sqft, ARRAY(0.25, 0.5, 0.75)) AS sqft_quartiles FROM stores GROUP BY CASE WHEN sqft >= 12300 THEN 'PREMIUM' ELSE 'STANDARD' END, city HAVING COUNT(DISTINCT city) >= 1 ORDER BY city NULLS LAST;
